  if (type === "resource.skill" && normalizedName === "create-specification" && specificationSignals) score += 60;
  if (type === "resource.tool" && readSignals && normalizedName === "read") score += 70;
  if (type === "resource.tool" && writeIntent && normalizedName === "write") score += 70;
  if (type === "resource.tool" && mutationIntent && (normalizedName === "edit" || normalizedName === "apply_patch")) score += 45;
  return score;
}

function requestMentionsResource(request, name) {
  const normalizedRequest = request.toLocaleLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const normalizedName = name.toLocaleLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (!normalizedName || !normalizedRequest.includes(normalizedName)) return false;
  if (normalizedName.includes(' ')) return true;
  const escaped = normalizedName.replaceAll('.', String.raw`\.`);
  const explicitAgentIdentity = new RegExp(String.raw`(?:\b(?:agent|subagent|delegate(?: to)?|use|call|invoke|existing|catalog|reference)\b[^.!?\n]{0,60}\b${escaped}\b|\b${escaped}\b[^.!?\n]{0,24}\b(?:agent|subagent)\b)`, 'i');
  return explicitAgentIdentity.test(request);
}

function containsAny(value, candidates) {
  const normalizedValue = ` ${value.replace(/[^a-z0-9]+/g, ' ').trim()} `;
  return candidates.some((candidate) => {
    if (!/^[a-z0-9 ]+$/i.test(candidate)) return value.includes(candidate);
    return normalizedValue.includes(` ${candidate.trim().toLocaleLowerCase().replace(/\s+/g, ' ')} `);
  });
}

function isExcludedResource(type, name) {
  const normalizedName = name.toLocaleLowerCase();
  return normalizedName === "error-recorder" || normalizedName.startsWith("workflow-") || (type === "resource.agent" && (normalizedName.includes("-writer-") || normalizedName.endsWith("-coordinator")));
}

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
